        <rect width="360" height="800" fill="white" transform="translate(0 -2)"/>
        </clipPath>
        </defs>
        </svg>
        """.trimIndent()
    }

    val imageBitmap = remember(configuration) {
        try {
            val svg = SVG.getFromString(svgCode)

            val widthPx = configuration.screenWidthDp
            val heightPx = configuration.screenHeightDp

            val bitmap = Bitmap.createBitmap(
                widthPx,
                heightPx,
                Bitmap.Config.ARGB_8888
            )

            val canvas = Canvas(bitmap)

            svg.setDocumentWidth(widthPx.toString())
            svg.setDocumentHeight(heightPx.toString())

            svg.renderToCanvas(canvas)

            bitmap.asImageBitmap()
        } catch (e: Exception) {
            null
        }
    }

    Box(
        modifier = modifier
            .fillMaxSize()
            .background(Color.White)
    ) {

        // Background
        imageBitmap?.let {
            Image(
                bitmap = it,
                contentDescription = null,
                modifier = Modifier.fillMaxSize(),
                contentScale = ContentScale.Crop
            )
        }

        // Foreground UI
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 32.dp)
                .padding(top = 100.dp, bottom = 56.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {

            Spacer(modifier = Modifier.weight(1f))
            Spacer(modifier = Modifier.weight(1.6f))

            Button(
                onClick = onSetUpClick,
                modifier = Modifier
                    .fillMaxWidth(0.72f)
                    .clip(RoundedCornerShape(50.dp)),
                shape = RoundedCornerShape(50.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = Color.Black,
                    contentColor = Color.White
                ),
                elevation = ButtonDefaults.buttonElevation(
                    defaultElevation = 8.dp,
                    pressedElevation = 2.dp
                )
            ) {
                Text(
                    text = "Set up",
                    fontSize = 20.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(vertical = 8.dp)
                )

                Text(
                    text = "           ▶",
                    fontSize = 26.sp,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }
}